/*!40000 ALTER TABLE `meetings` DISABLE KEYS */;
INSERT INTO `meetings` VALUES (5,1,1,'Pertemuan 1: Pengenalan & Konsep Dasar Matematika','Membahas pengenalan konsep dasar, tujuan pembelajaran, dan kompetensi awal mata pelajaran Matematika.','https://www.youtube.com/watch?v=DCdGyoyeih8',0,NULL,NULL,NULL,'2026-10-12 20:07:46','2026-10-12 20:07:46'),(6,1,2,'Pertemuan 2: Pendalaman Materi & Latihan Mandiri','Pendalaman materi, pembahasan studi kasus terstruktur, serta instruksi pengerjaan lembar kerja siswa (LKS).','https://www.youtube.com/watch?v=8UVfXaFwWsY',1,'Tugas 1: Lembar Kerja Siswa (LKS) Matematika','Pelajari modul pertemuan 2 dengan seksama. Kerjakan 5 soal latihan dan analisis kasus yang tercantum pada modul. Tuliskan jawaban secara rapi, lalu unggah berkas dalam format PDF sebelum tenggat waktu.','2026-10-20 05:07:46','2026-10-12 20:07:46','2026-10-12 20:07:46'),(7,1,3,'Pertemuan 3: Evaluasi Bab & Kuis Pemahaman','Sesi evaluasi capaian pemahaman belajar siswa pada materi Matematika melalui kuis interaktif pilihan ganda.','https://www.youtube.com/watch?v=0h94h93-x6U',0,NULL,NULL,NULL,'2026-10-12 20:07:46','2026-10-12 20:07:46'),(8,2,1,'Pertemuan 1: Pengenalan & Konsep Dasar IPA','Membahas pengenalan konsep dasar, tujuan pembelajaran, dan kompetensi awal mata pelajaran IPA.','https://www.youtube.com/watch?v=RFXPKzKm8Bw',0,NULL,NULL,NULL,'2026-10-12 20:07:46','2026-10-12 20:07:46'),(9,2,2,'Pertemuan 2: Pendalaman Materi & Latihan Mandiri','Pendalaman materi, pembahasan studi kasus terstruktur, serta instruksi pengerjaan lembar kerja siswa (LKS).','https://www.youtube.com/watch?v=7X3uK5_yTbg',1,'Tugas 1: Lembar Kerja Siswa (LKS) IPA','Pelajari modul pertemuan 2 dengan seksama. Kerjakan 5 soal latihan dan analisis kasus yang tercantum pada modul. Tuliskan jawaban secara rapi, lalu unggah berkas dalam format PDF sebelum tenggat waktu.','2026-10-20 05:07:46','2026-10-12 20:07:46','2026-10-12 20:07:46'),(10,2,3,'Pertemuan 3: Evaluasi Bab & Kuis Pemahaman','Sesi evaluasi capaian pemahaman belajar siswa pada materi